def _obj_get(obj: Any, key: str) -> Any:
    """Read `key` from a mapping or an attribute of an object.

    Perplexity SDK responses may be returned either as Pydantic models or plain
    dictionaries depending on the code path, so this helper normalizes access.
    """
    if isinstance(obj, Mapping):
        return obj.get(key)
    return getattr(obj, key, None)


def _dump(obj: Any) -> Any:
    """Return a plain-data representation of a Perplexity SDK model."""
    if hasattr(obj, "model_dump"):
        return obj.model_dump()
    return obj


def _tool_type(tool: Any) -> Any:
    """Return the `type` discriminator of a tool spec (mapping or object)."""
    return _obj_get(tool, "type")


def _use_responses_api(payload: dict) -> bool:
    """Determine whether a payload should be routed to the Responses (Agent) API.

    Args:
        payload: The request payload (merged model kwargs and call kwargs).

    Returns:
        `True` if the payload contains any built-in tool (a tool whose `type` is
        not `'function'`) or any of the Responses-only keys
        (`'previous_response_id'`, `'instructions'`, `'input'`, `'include'`).
        `False` for payloads with only function-type tools or no tools.
    """
    tools = payload.get("tools") or []
    uses_builtin_tools = any(_tool_type(tool) != "function" for tool in tools)
    return bool(uses_builtin_tools or _RESPONSES_ONLY_KEYS.intersection(payload))


def _convert_responses_usage(usage: Any) -> dict | None:
    """Convert Responses (Agent) API usage into a `UsageMetadata`-shaped dict.

    Args:
        usage: Usage object (or mapping) from a Responses API response.

    Returns:
        A dict with `input_tokens`, `output_tokens`, and `total_tokens`, or
        `None` if `usage` is missing or all token fields are `None`.
    """
    if usage is None:
        return None

    input_tokens = _obj_get(usage, "input_tokens")
    output_tokens = _obj_get(usage, "output_tokens")
    total_tokens = _obj_get(usage, "total_tokens")

    if input_tokens is None and output_tokens is None and total_tokens is None:
        return None

    if total_tokens is None and input_tokens is not None and output_tokens is not None:
        total_tokens = input_tokens + output_tokens

    return {
        "input_tokens": input_tokens or 0,
        "output_tokens": output_tokens or 0,
        "total_tokens": total_tokens or 0,
    }


def _collect_responses_extras(response: Any) -> dict[str, Any]:
    """Collect Perplexity-specific extras from a Responses (Agent) API response."""
    additional_kwargs: dict[str, Any] = {}
    search_results: list[Any] = []
    annotations: list[Any] = []
    for item in _obj_get(response, "output") or []:
        item_type = _obj_get(item, "type")
        if item_type == "search_results":
            search_results.extend(_dump(r) for r in (_obj_get(item, "results") or []))
        elif item_type == "message":
            for part in _obj_get(item, "content") or []:
                part_annotations = _obj_get(part, "annotations")
                if part_annotations:
                    annotations.extend(_dump(a) for a in part_annotations)
    if search_results:
        additional_kwargs["search_results"] = search_results
    if annotations:
        additional_kwargs["annotations"] = annotations
    return additional_kwargs


def _responses_response_metadata(response: Any, default_model: str | None) -> dict:
    """Build response metadata for a Responses (Agent) API response."""
    response_metadata: dict[str, Any] = {
        "model_name": _obj_get(response, "model") or default_model
    }
    for attr in ("id", "status", "created_at"):
        value = _obj_get(response, attr)
        if value is not None:
            response_metadata[attr] = value
    return response_metadata


